  "question_count": 2,
  "is_atomic": false,
  "atomic_questions": [
    "What is the objective of this production plan — for example, maximizing the number of complete products (each requiring one unit of each of the three components), maximizing total component output, or minimizing cost?",
    "Is there a demand or minimum quantity of complete products that must be met?"
  ],
  "rationale": "The response contains two semantically independent questions: one asking for the optimization objective and another asking about specific demand constraints."
}

